#!/bin/bash
#
# run_harbor_eval.sh - Run agentic benchmarks through Harbor (https://github.com/harbor-framework/
# harbor) against a model served behind an OpenAI-compatible endpoint. Each task is a container
# the agent works in; the task's own verifier scores the result (reward 0..1).
#
#   swe_bench          SWE-bench Verified, 500 tasks
#   swe_bench_pro      SWE-bench Pro v1 (public test split), 731 tasks
#   multi_swe_bench    Multi-SWE-bench, 1,632 tasks in 7 languages (generated by Harbor's adapter;
#                       --sandbox docker only: its Dockerfiles are multi-stage)
#   terminal_bench_2   Terminal-Bench 2.0, 89 tasks
#   terminal_bench_4   Terminal-Bench 4.0.0, 66 tasks
#   deep_swe           DeepSWE v1.1, 113 tasks
#   slop_code_bench    SlopCodeBench, 36 problems
#   senior_swe_bench   Senior SWE-bench v2026.06, 50 public tasks (--sandbox docker only: wildcard-
#                       hostname network allowlists, which a NetworkPolicy cannot express)
#   aider_polyglot     Aider Polyglot, 225 exercises
#
# The datasets are pinned in scripts/harbor_runner/run.py (BENCHMARKS). Harbor lives in its own
# venv (requirements/harbor-runtime.txt, pinned exactly; Python >= 3.12).
#
# Where the task containers run (--sandbox):
#   docker  Harbor's own Docker environment: a local Docker daemon (a laptop, a docker launcher).
#           The task images are linux/amd64 (emulated on Apple Silicon).
#   k8s     One unprivileged pod per trial through scripts/harbor_runner/k8s_environment.py, e.g.
#           in Breithorn's rob-poc namespace from a laptop or a Clariden job (Clariden's nodes are
#           aarch64 and have no Docker). Uses the current kubeconfig (or the in-cluster service
#           account); needs create/get/delete on pods and networkpolicies, create on pods/exec.
#           Tasks without a prebuilt image have their Dockerfile replayed in the pod; no-network
#           and allowlist tasks get a NetworkPolicy.
#   Default: k8s when running in a pod, else docker.
#
# Usage:
#   scripts/run_harbor_eval.sh --benchmark <b[,b...]> --model <served model> --api-base-url <url> [options]
#   scripts/run_harbor_eval.sh --benchmark <b[,b...]> --gold [options]
#
# Options:
#   --benchmark <b[,b]>        One or more of the names above, comma-separated.
#   --model <name>             Served model name at --api-base-url (the agent calls it through
#                               litellm as openai/<name>; terminus-2 needs no tool-call parser).
#   --api-base-url <url>       OpenAI-compatible endpoint (bare host or /v1 root).
#   --gold                      Harbor's oracle agent (each task's reference solution) instead of a
#                               model: a check of the environments and verifiers.
#   --agent <name>              Harbor agent (default: terminus-2; see `harbor run --help`).
#   --agent-kwarg <k=v>         Harbor --ak, repeatable, e.g. model_info='{"max_input_tokens": 32768}'
#                               so terminus-2 knows a served model's context window.
#   --name <name>              Run name (default: derived from --model).
#   --work-dir <path>          Output dir (default: logs/harbor/<name>): jobs/<benchmark>/ (Harbor's
#                               trials) and summary.json.
#   --sandbox docker|k8s       See above.
#   --limit <n>                 First n tasks per benchmark (smoke tests).
#   --task <glob>               Only tasks matching this name (repeatable).
#   --max-concurrency <n>       Trials in flight at once = containers alive at once (default: 4).
#   --attempts <n>              Attempts per task (default: 1; pass@k from more).
#   --timeout-multiplier <f>    Multiplies every task's timeouts (default: 1.0).
#
# Environment:
#   TARGET_API_KEY   key for --api-base-url (default: scripts/cscs_serving_api_key.txt).
#   HARBOR_VENV      venv to install into / run from (default: a cache dir keyed by the
#                    requirements file's hash).
#   SANDBOX_K8S_*  --sandbox k8s pod settings, shared with the EvalScope runner: namespace
#                    (SANDBOX_K8S_NAMESPACE), node arch, tolerations, memory request, run label
#                    (pods are labelled sandbox-run=<label>), pull secret, ready timeout. See
#                    scripts/k8s_sandbox.py.
#
# The run exits non-zero when any trial ended without a verifier reward (an infrastructure
# failure, listed under evaluation_errors in summary.json): its benchmark's score is incomplete.
#
# Examples:
#   scripts/run_harbor_eval.sh --benchmark swe_bench,terminal_bench_2 --gold --limit 2
#   SANDBOX_K8S_NAMESPACE=rob-poc scripts/run_harbor_eval.sh --benchmark swe_bench --sandbox k8s \
#     --model RCP-AIaaS/Qwen/Qwen3.6-35B-A3B --api-base-url https://api.swissai.svc.cscs.ch/v1 --limit 2
#   On Clariden: sbatch -p debug scripts/run_harbor_eval.sbatch --benchmark ... (see that script).

set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/.."

die() { echo "$*" >&2; exit 1; }

usage() {
    sed -n '2,/^set -euo/p' "${BASH_SOURCE[0]}" | sed '$d' | sed 's/^# \{0,1\}//'
}

MODEL=""
NAME=""
WORK_DIR=""
SANDBOX=""
GOLD=0
API_BASE_URL=${API_BASE_URL:-""}
RUN_ARGS=()

while (( $# > 0 )); do
    case "$1" in
        --model) MODEL=$2; shift 2 ;;
        --name) NAME=$2; shift 2 ;;
        --work-dir) WORK_DIR=$2; shift 2 ;;
        --sandbox) SANDBOX=$2; shift 2 ;;
        --api-base-url) API_BASE_URL=$2; shift 2 ;;
        --gold) GOLD=1; shift ;;
        --benchmark|--agent|--agent-kwarg|--limit|--task|--max-concurrency|--attempts|--timeout-multiplier)
            RUN_ARGS+=("$1" "$2"); shift 2 ;;
        -h|--help) usage; exit 0 ;;
        *) die "Unknown argument: $1 (see --help)" ;;
    esac
done

if [[ "$GOLD" == "1" ]]; then
    [[ -z "$MODEL" ]] || die "--gold runs the reference solutions; drop --model."
    MODEL_ARGS=(--gold)
else
    [[ -n "$MODEL" ]] || die "Missing --model (or --gold). See --help."
    [[ -n "$API_BASE_URL" ]] || die "Missing --api-base-url. See --help."
    [[ "$API_BASE_URL" == */v1 || "$API_BASE_URL" == */v1/ ]] || API_BASE_URL="${API_BASE_URL%/}/v1"
    MODEL_ARGS=(--model "$MODEL" --api-base-url "${API_BASE_URL%/}")
fi

if [[ -z "$SANDBOX" ]]; then
    [[ -f /var/run/secrets/kubernetes.io/serviceaccount/token ]] && SANDBOX=k8s || SANDBOX=docker
fi
[[ "$SANDBOX" == docker || "$SANDBOX" == k8s ]] || die "--sandbox must be docker or k8s, got: $SANDBOX"

NAME=${NAME:-$(echo "${MODEL:-gold}" | tr '/: ' '---')}
WORK_DIR=${WORK_DIR:-"logs/harbor/$NAME"}

CSCS_SERVING_API="${CSCS_SERVING_API:-}"
if [[ -z "$CSCS_SERVING_API" && -f ./scripts/cscs_serving_api_key.txt ]]; then
    CSCS_SERVING_API="$(tr -d '\r\n' < ./scripts/cscs_serving_api_key.txt)"
fi
# Not HARBOR_API_KEY: Harbor reads that as its Harbor Hub credential.
export EVAL_MODEL_API_KEY="${TARGET_API_KEY:-$CSCS_SERVING_API}"

# Harbor and the Multi-SWE-bench adapter are installed with uv (Harbor needs Python >= 3.12,
# which uv fetches where the system has none, e.g. Clariden's 3.6).
export PATH="$HOME/.local/bin:$PATH"
command -v uv >/dev/null 2>&1 || die "uv is required (https://docs.astral.sh/uv/)."
REQUIREMENTS=requirements/harbor-runtime.txt
req_hash=$( (sha256sum "$REQUIREMENTS" 2>/dev/null || shasum -a 256 "$REQUIREMENTS") | cut -c1-12)
HARBOR_VENV=${HARBOR_VENV:-"${XDG_CACHE_HOME:-$HOME/.cache}/evals-post-train/harbor-$req_hash"}
PY="$HARBOR_VENV/bin/python"
if [[ ! -f "$HARBOR_VENV/.installed-$req_hash" ]]; then
    echo "Installing $REQUIREMENTS into $HARBOR_VENV"
    { uv venv --quiet --allow-existing --python ">=3.12" "$HARBOR_VENV" &&
        uv pip install --quiet --python "$PY" -r "$REQUIREMENTS"; } ||
        die "Installing $REQUIREMENTS into $HARBOR_VENV failed."
    touch "$HARBOR_VENV/.installed-$req_hash"
fi

mkdir -p "$WORK_DIR"
CMD=("$PY" -m scripts.harbor_runner.run "${MODEL_ARGS[@]}" --work-dir "$WORK_DIR" --sandbox "$SANDBOX"
     ${RUN_ARGS[@]+"${RUN_ARGS[@]}"})
echo "Running: ${CMD[*]}"
"${CMD[@]}"
echo ""
echo "Done. Scores and run metadata: $WORK_DIR/summary.json"
